INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7467179, 1185464, 77196, '<td valign="top">But dark, grainy, undefined does not necessarily equals incomprehensible. Sometimes incomprehensible hits you square in the face with bright colors, distinct shapes, even obviously connected, but still incomprehensible. <br/>Nice connection between image and quote.</td>', 'But dark, grainy, undefined does not necessarily equals incomprehensible. Sometimes incomprehensible hits you square in the face with bright colors, distinct shapes, even obviously connected, but still incomprehensible. Nice connection between image and quote.', '2016-08-05 14:40:38.000000', NULL, 1),
(7467180, 1185418, 77196, '<td valign="top">Great texture and color. Oh, and nicely framed.</td>', 'Great texture and color. Oh, and nicely framed.', '2016-08-05 14:42:04.000000', NULL, 1),
(7467181, 1185439, 77196, '<td valign="top">One of the few fairly parsimonious quotes, and one I agree with. Nice capture of an instant of time. How many tries did it take to get the wings straight out? Great lighting.</td>', 'One of the few fairly parsimonious quotes, and one I agree with. Nice capture of an instant of time. How many tries did it take to get the wings straight out? Great lighting.', '2016-08-05 14:43:46.000000', NULL, 1),
(7467182, 1185443, 77196, '<td valign="top">I like the creativity, and the lighting. Especially the one eye just barely looking over the rim at you.</td>', 'I like the creativity, and the lighting. Especially the one eye just barely looking over the rim at you.', '2016-08-05 14:44:40.000000', NULL, 1),
(7467184, 1185476, 77196, '<td valign="top">Moody. Mysterious. Makes me wonder about what the building is or was, and where you''re standing to take the shot.</td>', 'Moody. Mysterious. Makes me wonder about what the building is or was, and where you''re standing to take the shot.', '2016-08-05 14:45:31.000000', NULL, 1),
(7467185, 1185432, 77196, '<td valign="top">Great clouds, color, and light!</td>', 'Great clouds, color, and light!', '2016-08-05 14:46:03.000000', NULL, 1),
(7467186, 1185297, 77196, '<td valign="top">Something doesn''t quite match up in her pose vs. her expression. I see the pose as indicating she is about to take decisive action. Her expression speaks of fear and indecision. Love the reds.</td>', 'Something doesn''t quite match up in her pose vs. her expression. I see the pose as indicating she is about to take decisive action. Her expression speaks of fear and indecision. Love the reds.', '2016-08-05 14:48:30.000000', NULL, 1),
(7467187, 1185107, 77196, '<td valign="top">Unfortunate alignment of yellow rope and the ball in the lady-in-the-circle''s hand - almost looks like she''s pulling it towards her. Interesting contrast between the three people looking like they''re at a wake or some dead serious event, and the other two that look like they''re all happy and energetic - especially the lady on the left.</td>', 'Unfortunate alignment of yellow rope and the ball in the lady-in-the-circle''s hand - almost looks like she''s pulling it towards her. Interesting contrast between the three people looking like they''re at a wake or some dead serious event, and the other two that look like they''re all happy and energetic - especially the lady on the left.', '2016-08-05 14:52:33.000000', NULL, 1),
(7467188, 1185470, 77196, '<td valign="top">And not to stand. This made me smile. A nice trade-off between the danger of the tracks (train/tram?) and whimsical graffiti.</td>', 'And not to stand. This made me smile. A nice trade-off between the danger of the tracks (train/tram?) and whimsical graffiti.', '2016-08-05 14:54:21.000000', NULL, 1),
(7467189, 1185158, 77196, '<td valign="top">Great shot! Beautiful sky, sharp image, crisp focus on talons and eyes. Nit-picky - coloring on top of the head makes it blend into the pattern on the underside of wing.</td>', 'Great shot! Beautiful sky, sharp image, crisp focus on talons and eyes. Nit-picky - coloring on top of the head makes it blend into the pattern on the underside of wing.', '2016-08-05 14:55:58.000000', NULL, 1),
(7467190, 1185477, 77196, '<td valign="top">Great use of color and motion.</td>', 'Great use of color and motion.', '2016-08-05 14:56:26.000000', NULL, 1),
(7467191, 1185472, 77196, '<td valign="top">The ripple reflections make it look like the side of the boat isn''t smooth. Nice colors. The bird looks content.</td>', 'The ripple reflections make it look like the side of the boat isn''t smooth. Nice colors. The bird looks content.', '2016-08-05 15:00:07.000000', NULL, 1),
(7467192, 1185269, 77196, '<td valign="top">Interesting enigma of an image.</td>', 'Interesting enigma of an image.', '2016-08-05 15:01:14.000000', NULL, 1),
